# Code generated by Claude
"""The robot's outline from above for the navigation core, derived from the compiled model (overnight queue stage 2; navigation proposal N4).

    fp = robot_footprint(model, data, pedestal_q)       # {"polygon": (K, 2) base frame, "r_in", "r_out", "h_top"}

The outline is the convex hull, seen from above, of the surface of every collision geom of the robot (the base, the battery, the pedestal and torso, the neck, both arms and hands at the zombie pose with the
fingers open) with the pedestal at the drive height; `h_top` is the highest point above the floor. The inscribed radius is the smallest distance from the base origin to an edge of the polygon and the
circumscribed radius the largest distance to a vertex. Today's staging drives with the arms at the zombie pose at `TASK_CFG["pedestal_q"]`.

Contents:
    robot_footprint.
"""

import mujoco
import numpy as np
from scipy.spatial import ConvexHull

from src.home_clearance_map import surface_samples
from src.nav_grid import footprint_radii
from src.stance_checks import StanceChecks
from src.stance_finder import robot_geometry


def robot_footprint(model, data, pedestal_q, spacing=0.02):
    """The footprint polygon, radii and height of the robot at a pedestal command.

    Args:
        model (mujoco.MjModel): The compiled model (with the neck and the battery).
        data (mujoco.MjData): Its data (any state).
        pedestal_q (float): The drive pedestal command, metres.
        spacing (float): The surface sample spacing, metres. Defaults to 0.02.

    Returns:
        dict: "polygon" ((K, 2) the convex outline in the base frame, x forward, y left, metres), "r_in", "r_out" (metres), "h_top" (the robot's top above the floor, metres).
    """
    chk = StanceChecks(model, data, robot_geometry(model)["base_z"])
    chk.place((0.0, 0.0, 0.0, float(pedestal_q)))
    d = chk.d
    root = model.body("base_link").id

    def under(b):
        while b > 0:
            if b == root:
                return True
            b = int(model.body_parentid[b])
        return False
    pts = [surface_samples(model, d, g, spacing) for g in range(model.ngeom)
           if (model.geom_contype[g] or model.geom_conaffinity[g]) and under(int(model.geom_bodyid[g]))]
    P = np.concatenate(pts)
    hull = ConvexHull(P[:, :2])
    poly = P[hull.vertices, :2]
    r_in, r_out = footprint_radii(poly)
    return {"polygon": poly, "r_in": r_in, "r_out": r_out, "h_top": float(P[:, 2].max())}
